/**
 * The bundled icons (21.1): Tabler, MIT, outline and filled.
 *
 * The index is generated by `npm run build:icons` and loaded on first open of
 * the picker, never with the app: five thousand icons are about 400KB
 * compressed, which is a fine price for the screen that uses them and a bad
 * one for every other screen.
 *
 * An inserted icon is an ordinary `path` layer carrying its own path data. It
 * renders and exports without the index, in the brand's colours, and its
 * `icon` stamp only tells the picker which style the deck already uses.
 */

import { makeLayer, type Doc, type Layer } from "./model.js";

export type IconStyle = "outline" | "filled";

export const ICON_SET: Record<IconStyle, string> = { outline: "tabler-outline", filled: "tabler-filled" };
export const STYLE_LABEL: Record<IconStyle, string> = { outline: "Outline", filled: "Filled" };

export type IconIndex = { icons: Record<string, string>; words: Record<string, string> };

const cache = new Map<IconStyle, Promise<IconIndex>>();

/** Loads one style's icons and the shared search words, once per session. */
export function loadIcons(style: IconStyle): Promise<IconIndex> {
  let hit = cache.get(style);
  if (!hit) {
    hit = Promise.all([
      style === "outline"
        ? import("../render/iconsets/tabler-outline.json")
        : import("../render/iconsets/tabler-filled.json"),
      import("../render/iconsets/tabler-words.json"),
    ]).then(([icons, words]) => ({
      icons: (icons as { default: Record<string, string> }).default,
      words: (words as { default: Record<string, string> }).default,
    }));
    cache.set(style, hit);
  }
  return hit;
}

/**
 * Icons matching every word of the query, best first: an exact name, then a
 * name that starts with it, then a name containing it, then a tag. Ties by
 * name, so the same query always lists the same icons in the same order.
 */
export function searchIcons(query: string, index: IconIndex, limit = 120): string[] {
  const terms = query.toLowerCase().split(/\s+/).filter(Boolean);
  const names = Object.keys(index.icons);
  if (terms.length === 0) return names.sort().slice(0, limit);
  const first = terms.join("-");
  const scored: [string, number][] = [];
  for (const name of names) {
    const hay = `${name} ${index.words[name] ?? ""}`;
    if (!terms.every((t) => hay.includes(t))) continue;
    const score = name === first ? 0 : name.startsWith(first) ? 1 : name.includes(first) ? 2 : 3;
    scored.push([name, score]);
  }
  return scored
    .sort((a, b) => a[1] - b[1] || a[0].localeCompare(b[0]))
    .slice(0, limit)
    .map(([n]) => n);
}

/** The style a deck already uses, from the icons on it, or null when it has none. */
export function deckIconStyle(doc: Doc): IconStyle | null {
  for (const s of doc.slides) {
    for (const l of s.layers) {
      if (l.icon?.set === ICON_SET.filled) return "filled";
      if (l.icon?.set === ICON_SET.outline) return "outline";
    }
  }
  // No icon yet: the style pack's choice (25.6), when there was one.
  return doc.iconStyle ?? null;
}

/**
 * An icon as a layer: outline drawn as a 2-unit stroke on Tabler's 24-unit
 * grid (the weight it was designed at, at any size), filled drawn as a fill.
 * One colour, the brand's accent by default, like every other mark.
 */
export function iconLayer(
  name: string,
  d: string,
  style: IconStyle,
  at: { x: number; y: number; size: number },
  colour: string,
): Layer {
  const base = makeLayer("path", { x: at.x, y: at.y, w: at.size, h: at.size }, style === "filled" ? colour : "none");
  return {
    ...base,
    name,
    path: d,
    pathW: 24,
    pathH: 24,
    scaleStroke: true,
    icon: { set: ICON_SET[style], name },
    ...(style === "outline" ? { stroke: colour, strokeWidth: 2 } : { stroke: null, strokeWidth: 0 }),
  };
}
